<?php
$conn = new mysqli('localhost', 'root', '', 'borrow_db');
if ($conn->connect_error) die('เชื่อมต่อฐานข้อมูลไม่ได้');
$conn->set_charset('utf8mb4');$columns=['sub_item_name'=>"VARCHAR(150) NOT NULL DEFAULT ''",'serial_number'=>"VARCHAR(100) NOT NULL DEFAULT ''",'borrower_phone'=>"VARCHAR(30) NOT NULL DEFAULT ''",'borrow_duration'=>"VARCHAR(100) NOT NULL DEFAULT ''",'lender_name'=>"VARCHAR(100) NOT NULL DEFAULT ''",'return_image_path'=>"TEXT NULL",'return_time'=>"DATETIME NULL",'condition_status'=>"VARCHAR(30) NOT NULL DEFAULT 'pending'",'condition_note'=>"TEXT NULL"];
foreach($columns as $name=>$definition){$check=$conn->query("SHOW COLUMNS FROM transactions LIKE '$name'");if($check && !$check->num_rows)$conn->query("ALTER TABLE transactions ADD COLUMN `$name` $definition");}
$sort = strtolower($_GET['sort'] ?? 'desc');
$sort = in_array($sort, ['asc', 'desc'], true) ? $sort : 'desc';
$sortBy = strtolower($_GET['sort_by'] ?? 'id');
$sortableColumns = ['id' => 'id', 'borrow' => 'record_time', 'return' => 'return_time'];
$sortBy = array_key_exists($sortBy, $sortableColumns) ? $sortBy : 'id';
$nextSort = $sort === 'asc' ? 'desc' : 'asc';
$sortIcon = $sort === 'asc' ? '↑' : '↓';
$result=$conn->query("SELECT * FROM transactions WHERE action_type='Borrow' ORDER BY `".$sortableColumns[$sortBy]."` ".strtoupper($sort).", id DESC");
function first_image($value){$images=array_values(array_filter(array_map('trim',explode(',',(string)$value))));return$images[0]??'';}
function image_list($value){return array_values(array_filter(array_map('trim',explode(',',(string)$value))));}
function e($value){return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
function loan_duration($borrowTime,$returnTime=null){
    try{
        $start=new DateTimeImmutable($borrowTime);
        $end=$returnTime?new DateTimeImmutable($returnTime):new DateTimeImmutable('now');
        $diff=$start->diff($end);
        $parts=[];
        if($diff->y)$parts[]=$diff->y.' ปี';
        if($diff->m)$parts[]=$diff->m.' เดือน';
        if($diff->d)$parts[]=$diff->d.' วัน';
        if($diff->h)$parts[]=$diff->h.' ชั่วโมง';
        if($diff->i)$parts[]=$diff->i.' นาที';
        return $parts?implode(' ',array_slice($parts,0,2)):'น้อยกว่า 1 นาที';
    }catch(Exception $exception){return '-';}
}
