<?php if($result &&$result->num_rows): while($row=$result->fetch_assoc()): $borrowImages=image_list($row['image_path']);$returnImages=image_list($row['return_image_path']);$borrowImage=first_image($row['image_path']);$returnImage=first_image($row['return_image_path']);$dueDays=(int)$row['borrow_duration'];if($dueDays<1)$dueDays=7;$isOverdue=!$row['return_time']&&(time()-strtotime($row['record_time']) >= $dueDays*86400);$status=$row['return_time']?($row['condition_status']?:'needs_review'):($isOverdue?'overdue':'pending');$labels=['pending'=>'กำลังยืมอยู่','good'=>'ปกติ','damaged'=>'พบความเสียหาย','needs_review'=>'รอตรวจสอบ']; $labels['overdue']=html_entity_decode('&#3648;&#3585;&#3636;&#3609;&#3619;&#3632;&#3618;&#3632;&#3648;&#3623;&#3621;&#3634;&#3585;&#3634;&#3619;&#3618;&#3639;&#3617;&#3607;&#3637;&#3656;&#3585;&#3635;&#3627;&#3609;&#3604;',ENT_QUOTES,'UTF-8');$photoData=e(json_encode(['id'=>(int)$row['id'],'borrow'=>$borrowImages,'return'=>$returnImages,'borrower'=>$row['borrower_name'],'item'=>$row['item_name'],'status'=>$labels[$status]??'รอตรวจสอบ','note'=>$row['condition_note']],JSON_UNESCAPED_UNICODE));$detailData=e(json_encode(['id'=>$row['id'],'borrower'=>$row['borrower_name'],'phone'=>$row['borrower_phone'],'lender'=>$row['lender_name'],'item'=>$row['item_name'],'subItem'=>$row['sub_item_name'],'duration'=>$row['borrow_duration'],'borrowTime'=>date('d/m/Y H:i',strtotime($row['record_time'])),'returnTime'=>$row['return_time']?date('d/m/Y H:i',strtotime($row['return_time'])):'ยังไม่มีหลักฐานรับคืน','status'=>$labels[$status]??'รอตรวจสอบ','note'=>$row['condition_note'],'borrow'=>$borrowImages,'return'=>$returnImages],JSON_UNESCAPED_UNICODE)); ?>
<tr><td><?= (int)$row['id'] ?></td><td><div class="person"><?=e($row['borrower_name'])?></div><?php if($row['borrower_phone']):?><div class="muted"><?=e($row['borrower_phone'])?></div><?php endif;?></td><td><div class="person"><?=e($row['item_name'])?></div><?php if($row['sub_item_name'] || $row['serial_number']):?><div class="muted"><?=e($row['sub_item_name'] ?: $row['serial_number'])?></div><?php endif;?></td><td class="duration-cell" data-start="<?=e(date('c',strtotime($row['record_time'])))?>" data-end="<?=e($row['return_time']?date('c',strtotime($row['return_time'])):'')?>" data-days="<?=$dueDays?>"><span class="duration-value"></span></td><td><?=date('d/m/Y H:i',strtotime($row['record_time']))?></td><td><?php if($borrowImage):?><button class="photo-btn view-one" data-comparison='<?=$photoData?>'><img src="<?=e($borrowImage)?>" alt="รูปการส่งมอบ"><span>ดูหลักฐานส่งมอบ<?=count($borrowImages)>1?' ('.count($borrowImages).')':''?></span></button><?php else:?><span class="none">ไม่มีรูป</span><?php endif;?></td><td><?= $row['return_time']?date('d/m/Y H:i',strtotime($row['return_time'])):'—' ?></td><td><?php if($returnImage):?><div class="return-photo-card"><button class="photo-btn view-one" data-comparison='<?=$photoData?>'><img src="<?=e($returnImage)?>" alt="&#3619;&#3641;&#3611;&#3585;&#3634;&#3619;&#3619;&#3633;&#3610;&#3588;&#3639;&#3609;"><span>&#3604;&#3641;&#3627;&#3621;&#3633;&#3585;&#3600;&#3634;&#3609;&#3619;&#3633;&#3610;&#3588;&#3639;&#3609;<?=count($returnImages)>1?' ('.count($returnImages).')':''?></span></button></div><?php else:?><span class="none">&#3618;&#3633;&#3591;&#3652;&#3617;&#3656;&#3617;&#3637;&#3627;&#3621;&#3633;&#3585;&#3600;&#3634;&#3609;&#3619;&#3633;&#3610;&#3588;&#3639;&#3609;</span><button type="button" class="return-entry" data-id="<?= (int)$row['id'] ?>" data-borrower="<?=e($row['borrower_name'])?>" data-item="<?=e($row['item_name'])?>">&#43;&#32;&#3610;&#3633;&#3609;&#3607;&#3638;&#3585;&#3585;&#3634;&#3619;&#3619;&#3633;&#3610;&#3588;&#3639;&#3609;</button><?php endif;?></td><td><span class="state <?=e($status)?>"><?=e($labels[$status]??'รอตรวจสอบ')?></span><?php if($row['condition_note']):?><div class="muted"><?=e($row['condition_note'])?></div><?php endif;?></td><td><div class="manage"><a class="detail-action" href="history_detail.php?id=<?= (int)$row['id'] ?>">&#3619;&#3634;&#3618;&#3621;&#3632;&#3648;&#3629;&#3637;&#3618;&#3604;</a><a class="edit-action" href="history_detail.php?id=<?= (int)$row['id'] ?>&amp;edit=1">&#9998; &#3649;&#3585;&#3657;&#3652;&#3586;</a></div></td></tr>
<?php endwhile;else:?><tr><td colspan="10">ยังไม่มีประวัติการยืม</td></tr><?php endif;?></tbody></table></div></main>
<div class="modal" id="formModal" aria-hidden="true"><div class="modal-box form-modal-box"><button class="close form-close" type="button" aria-label="???">?</button><h2 id="formModalTitle">'+ent(u(r'ยืมอุปกรณ์'))+'</h2><iframe id="formFrame" title="ItemFlow transaction form" src="about:blank"></iframe></div></div>
<div class="modal" id="modal"><div class="modal-box"><button class="close" aria-label="ปิด">×</button><h2 id="modalTitle">รายละเอียดรูปภาพอุปกรณ์</h2><div class="compare-grid"><section class="image-panel"><h3>การส่งมอบ</h3><div id="borrowPanel"></div></section><section class="image-panel"><h3>การรับคืน</h3><div id="returnPanel"></div></section></div><div class="note" id="modalNote"></div></div></div>
<div class="modal" id="detailModal"><div class="modal-box"><button class="close" aria-label="ปิด">×</button><h2 id="detailTitle">รายละเอียดรายการ</h2><div class="detail-grid" id="detailGrid"></div><div class="compare-grid"><section class="image-panel"><h3>รูปการส่งมอบ</h3><div id="detailBorrowPhotos"></div></section><section class="image-panel"><h3>รูปการรับคืน</h3><div id="detailReturnPhotos"></div></section></div></div></div>
<script>
const codeHeader=document.querySelector('.table-wrap thead th:first-child');
if(codeHeader){const nextSort='<?= $nextSort ?>',sortIcon='<?= $sortIcon ?>';codeHeader.innerHTML=`<a class="sort-code" href="?sort=${nextSort}" title="คลิกเพื่อเรียงรหัส">ลำดับ <span class="arrow">${sortIcon}</span></a>`;}
const modal=document.getElementById('modal'),title=document.getElementById('modalTitle'),borrowPanel=document.getElementById('borrowPanel'),returnPanel=document.getElementById('returnPanel'),note=document.getElementById('modalNote');
document.querySelectorAll('.duration-cell').forEach(cell=>{const start=Date.parse(cell.dataset.start),end=cell.dataset.end?Date.parse(cell.dataset.end):null;if(Number.isNaN(start))return;const paint=()=>{let seconds=Math.max(0,Math.floor(((end??Date.now())-start)/1000));const days=Math.floor(seconds/86400);seconds%=86400;const hours=Math.floor(seconds/3600);seconds%=3600;const minutes=Math.floor(seconds/60);seconds%=60;const dayText=days?`${days} \u0e27\u0e31\u0e19 `:'';cell.querySelector('.duration-value').innerHTML=`${dayText}${hours} \u0e0a\u0e21<br>${minutes} \u0e19\u0e32\u0e17\u0e35 ${seconds} \u0e27\u0e34\u0e19\u0e32\u0e17\u0e35`;if(!end){const pill=cell.parentElement.cells[8].querySelector('.state'),overdue=Date.now()>=start+(Number(cell.dataset.days)||7)*86400000;pill.classList.toggle('pending',!overdue);pill.classList.toggle('overdue',overdue);pill.textContent=overdue?'\u0e40\u0e01\u0e34\u0e19\u0e23\u0e30\u0e22\u0e30\u0e40\u0e27\u0e25\u0e32\u0e01\u0e32\u0e23\u0e22\u0e37\u0e21\u0e17\u0e35\u0e48\u0e01\u0e33\u0e2b\u0e19\u0e14':'\u0e01\u0e33\u0e25\u0e31\u0e07\u0e22\u0e37\u0e21\u0e2d\u0e22\u0e39\u0e48';}};paint();if(!end)setInterval(paint,1000);});

if(codeHeader){const tableNextSort='<?= $nextSort ?>',tableSortIcon='<?= $sortIcon ?>';codeHeader.innerHTML=`<a class="sort-code" href="?sort=${tableNextSort}" title="Sort order">\u0e25\u0e33\u0e14\u0e31\u0e1a <span class="arrow">${tableSortIcon}</span></a>`;}

const activeSortBy='<?= $sortBy ?>',activeSort='<?= $sort ?>',nextSort='<?= $nextSort ?>',activeSortIcon='<?= $sortIcon ?>';
const sortableHeaders={0:['id','\u0e25\u0e33\u0e14\u0e31\u0e1a'],4:['borrow','\u0e27\u0e31\u0e19\u0e41\u0e25\u0e30\u0e40\u0e27\u0e25\u0e32\u0e2a\u0e48\u0e07\u0e21\u0e2d\u0e1a'],6:['return','\u0e27\u0e31\u0e19\u0e41\u0e25\u0e30\u0e40\u0e27\u0e25\u0e32\u0e23\u0e31\u0e1a\u0e04\u0e37\u0e19']};
Object.entries(sortableHeaders).forEach(([index,[key,label]])=>{const header=document.querySelector(`.table-wrap thead th:nth-child(${Number(index)+1})`),isActive=key===activeSortBy,direction=isActive?nextSort:'asc';if(header)header.innerHTML=`<a class="sort-code" href="?sort_by=${key}&sort=${direction}" title="Sort order">${label} <span class="arrow">${isActive?activeSortIcon:'↕'}</span></a>`;});
document.querySelectorAll('.compare').forEach(link=>{const id=new URL(link.href,location.href).searchParams.get('id');if(id)link.insertAdjacentHTML('afterend',`<a class="edit-link" href="history_detail.php?id=${id}&edit=1">\u0e41\u0e01\u0e49\u0e44\u0e02</a>`);});
function panel(el,images){el.innerHTML=images&&images.length?`<img src="${images[0]}" alt="รูปภาพอุปกรณ์">${images.length>1?`<div class="muted">แสดงรูปแรกจากทั้งหมด ${images.length} รูป</div>`:''}`:'<div class="none">ยังไม่มีรูปภาพ</div>'}
function openModal(data){title.textContent=`\u0e23\u0e32\u0e22\u0e25\u0e30\u0e40\u0e2d\u0e35\u0e22\u0e14\u0e23\u0e39\u0e1b\u0e20\u0e32\u0e1e: ${data.item} \u2014 ${data.borrower}`;panel(borrowPanel,data.borrow);panel(returnPanel,data.return);note.textContent=`\u0e1c\u0e25\u0e15\u0e23\u0e27\u0e08\u0e2a\u0e20\u0e32\u0e1e: ${data.status}${data.note?' | \u0e2b\u0e21\u0e32\u0e22\u0e40\u0e2b\u0e15\u0e38: '+data.note:''}`;if(data.return&&data.return.length){const add=document.createElement('button');add.type='button';add.className='modal-add-return';add.textContent='\u002b \u0e40\u0e1e\u0e34\u0e48\u0e21\u0e2b\u0e25\u0e31\u0e01\u0e10\u0e32\u0e19';add.onclick=()=>{modal.classList.remove('show');const params=new URLSearchParams({form:'return',id:data.id,borrower:data.borrower,item:data.item});openTransactionForm('index.php?'+params.toString(),'\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e2b\u0e25\u0e31\u0e01\u0e10\u0e32\u0e19\u0e04\u0e37\u0e19')};returnPanel.appendChild(add)}modal.classList.add('show')}
document.querySelectorAll('.view-one').forEach(b=>b.onclick=()=>openModal(JSON.parse(b.dataset.comparison)));
document.querySelectorAll('.modal .close:not(.form-close)').forEach(button=>button.addEventListener('click',()=>button.closest('.modal').classList.remove('show')));document.querySelectorAll('.modal:not(#formModal)').forEach(overlay=>overlay.addEventListener('click',event=>{if(event.target===overlay)overlay.classList.remove('show')}));
document.querySelectorAll('.delete').forEach(b=>b.onclick=async()=>{if(!confirm('ต้องการลบรายการนี้หรือไม่?'))return;const t=await (await fetch('save_record.php?action=delete&id='+b.dataset.id)).text();alert(t);location.reload()});document.getElementById('deleteAll').onclick=async()=>{if(!confirm('ต้องการลบประวัติทั้งหมดหรือไม่?'))return;const t=await (await fetch('save_record.php?action=delete_all')).text();alert(t);location.reload()};

const formModal=document.getElementById('formModal'),formFrame=document.getElementById('formFrame'),formTitle=document.getElementById('formModalTitle');
function openTransactionForm(url,titleText){formTitle.textContent=titleText;formModal.classList.add('show');formModal.setAttribute('aria-hidden','false');formFrame.src=url;}
document.getElementById('borrowOpen').addEventListener('click',()=>openTransactionForm('index.php?form=borrow','ยืมอุปกรณ์'));
document.querySelectorAll('.return-entry').forEach(button=>button.addEventListener('click',()=>{const params=new URLSearchParams({form:'return',id:button.dataset.id,borrower:button.dataset.borrower,item:button.dataset.item}),title=button.classList.contains('add-return-image')?'\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e2b\u0e25\u0e31\u0e01\u0e10\u0e32\u0e19\u0e04\u0e37\u0e19':'\u0e1a\u0e31\u0e19\u0e17\u0e36\u0e01\u0e1a\u0e31\u0e19\u0e17\u0e36\u0e01\u0e01\u0e32\u0e23\u0e23\u0e31\u0e1a\u0e04\u0e37\u0e19';openTransactionForm('index.php?'+params.toString(),title);}));
document.querySelector('.form-close').addEventListener('click',()=>{formModal.classList.remove('show');formModal.setAttribute('aria-hidden','true');formFrame.src='about:blank';});
formModal.addEventListener('click',event=>{if(event.target===formModal){formModal.classList.remove('show');formModal.setAttribute('aria-hidden','true');formFrame.src='about:blank';}});
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='itemflow-saved')return;formModal.classList.remove('show');formModal.setAttribute('aria-hidden','true');formFrame.src='about:blank';location.reload();});
</script></body></html>









